/* eslint-disable sort-keys */
import type { Meta, StoryObj } from "@storybook/react";
import { id } from "date-fns/locale";
import { useState } from "react";

import { DateTimePicker } from "./date-time-picker";

const meta = {
  argTypes: {
    clearable: { control: "boolean" },
    dateFormat: { control: "text" },
    defaultValue: { control: false },
    disabled: { control: "boolean" },
    disabledDates: { control: false },
    label: { control: "text" },
    locale: { control: false },
    motion: { control: "boolean" },
    onOpenChange: { control: false },
    onValueChange: { control: false },
    open: { control: false },
    placeholder: { control: "text" },
    hourCycle: { control: "inline-radio", options: [12, 24] },
    precision: { control: "inline-radio", options: ["minute", "second"] },
    readOnly: { control: "boolean" },
    value: { control: false },
  },
  args: {
    clearable: true,
    dateFormat: "PPP p",
    disabled: false,
    label: "Starts at",
    motion: true,
    placeholder: "Select date and time",
    precision: "minute",
    readOnly: false,
  },
  component: DateTimePicker,
  parameters: { layout: "centered" },
  tags: ["autodocs"],
  title: "Vandor UI/DateTimePicker",
} satisfies Meta<typeof DateTimePicker>;

export default meta;
type Story = StoryObj<typeof meta>;
export const Playground: Story = {};
export const Populated: Story = {
  args: { defaultValue: new Date(2026, 9, 5, 14, 30) },
};
export const WithSeconds: Story = {
  args: {
    ...Populated.args,
    dateFormat: "PPP pp",
    precision: "second",
  },
};
export const TwentyFourHour: Story = {
  args: { ...Populated.args, dateFormat: "PPP HH:mm", hourCycle: 24 },
};
export const ReadOnly: Story = { args: { ...Populated.args, readOnly: true } };
export const Disabled: Story = { args: { disabled: true } };
export const Indonesian: Story = {
  args: { ...Populated.args, dateFormat: "PPP HH:mm", locale: id },
};
export const WithoutMotion: Story = { args: { motion: false } };
export const Controlled: Story = {
  render: function ControlledPicker(args) {
    const [date, setDate] = useState<Date>();
    return <DateTimePicker {...args} value={date} onValueChange={setDate} />;
  },
};
